CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE TABLE memos (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Text" text NOT NULL,
    "AuthorId" integer NOT NULL,
    "Period" daterange NOT NULL,
    CONSTRAINT "PK_memos" PRIMARY KEY ("Id")
);

CREATE TABLE tickets (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Code" text NOT NULL,
    "Title" text NOT NULL,
    "OwnerId" integer NOT NULL,
    "QueueId" integer NOT NULL,
    "Period" daterange NOT NULL,
    "ClosedOn" date,
    "DeletedOn" date,
    "Label_Code" text NOT NULL,
    "Label_Name" text NOT NULL,
    CONSTRAINT "PK_tickets" PRIMARY KEY ("Id")
);

CREATE UNIQUE INDEX ux_memo_text ON memos ("Text");

CREATE UNIQUE INDEX ux_ticket_label_code_open ON tickets ("Label_Code") WHERE ("ClosedOn" IS NULL) AND ("DeletedOn" IS NULL);

CREATE UNIQUE INDEX ux_ticket_label_name ON tickets ("Label_Name") WHERE "DeletedOn" IS NULL;

CREATE UNIQUE INDEX ux_ticket_code ON tickets ("Code") WHERE "DeletedOn" IS NULL;

CREATE UNIQUE INDEX ux_ticket_queue_code_open ON tickets ("QueueId", "Code") WHERE ("ClosedOn" IS NULL) AND ("DeletedOn" IS NULL);

CREATE UNIQUE INDEX ux_ticket_owner_title_open ON tickets ("OwnerId", "Title") WHERE (("ClosedOn" IS NULL AND "QueueId" > 0)) AND ("DeletedOn" IS NULL);

CREATE UNIQUE INDEX ux_ticket_title_lower_open ON tickets ((lower("Title"))) WHERE ("ClosedOn" IS NULL) AND ("DeletedOn" IS NULL);

CREATE INDEX ix_ticket_owner ON tickets ("OwnerId");

CREATE INDEX ix_ticket_queue_open ON tickets ("QueueId") WHERE "ClosedOn" IS NULL;

ALTER TABLE "memos" DROP CONSTRAINT IF EXISTS "ex_memo_author";
ALTER TABLE "memos" ADD CONSTRAINT "ex_memo_author" EXCLUDE USING gist ("AuthorId" WITH =, "Period" WITH &&);

ALTER TABLE "tickets" DROP CONSTRAINT IF EXISTS "ex_ticket_owner";
ALTER TABLE "tickets" ADD CONSTRAINT "ex_ticket_owner" EXCLUDE USING gist ("OwnerId" WITH =, "Period" WITH &&) WHERE ("DeletedOn" IS NULL);

ALTER TABLE "tickets" DROP CONSTRAINT IF EXISTS "ex_ticket_queue_open";
ALTER TABLE "tickets" ADD CONSTRAINT "ex_ticket_queue_open" EXCLUDE USING gist ("QueueId" WITH =, "Period" WITH &&) WHERE (("ClosedOn" IS NULL) AND ("DeletedOn" IS NULL));

ALTER TABLE "tickets" DROP CONSTRAINT IF EXISTS "ex_ticket_owner_queue_open";
ALTER TABLE "tickets" ADD CONSTRAINT "ex_ticket_owner_queue_open" EXCLUDE USING gist ("OwnerId" WITH =, "QueueId" WITH =, "Period" WITH &&) WHERE ((("ClosedOn" IS NULL AND "QueueId" > 0)) AND ("DeletedOn" IS NULL));

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20260101000000_Initial', '10.0.15');

COMMIT;

